        setHudBar(
          'sec',
          `CYCLE ROYAL — ${this.royalCycle.state}`,
          (this.royalCycle.integrity / this.royalCycle.maxIntegrity) * 100,
          `${Math.ceil(this.royalCycle.integrity)}/${this.royalCycle.maxIntegrity}`
        );
